const fs = require('fs');
const path = require('path');
const crypto = require('crypto');
const multer = require('multer');
const { HttpError } = require('../utils/errors');

const UPLOAD_DIR = path.join(__dirname, '..', '..', 'uploads');
fs.mkdirSync(UPLOAD_DIR, { recursive: true });

const EXT_BY_MIME = {
  'image/jpeg': '.jpg',
  'image/png': '.png',
  'image/webp': '.webp',
};

const MAX_BYTES = 5 * 1024 * 1024; // 5 MB

// The filename is generated by the server (random), never taken from the user.
const storage = multer.diskStorage({
  destination: UPLOAD_DIR,
  filename: (req, file, cb) => {
    cb(null, crypto.randomBytes(16).toString('hex') + EXT_BY_MIME[file.mimetype]);
  },
});

const upload = multer({
  storage,
  limits: { fileSize: MAX_BYTES, files: 1 },
  fileFilter: (req, file, cb) => {
    if (!EXT_BY_MIME[file.mimetype]) {
      return cb(new HttpError(400, 'Only JPG, PNG or WebP images are allowed'));
    }
    cb(null, true);
  },
});

// The MIME type sent by the browser can be faked, so we also check the real file signature.
function looksLikeImage(buf) {
  const jpg = buf[0] === 0xff && buf[1] === 0xd8 && buf[2] === 0xff;
  const png = buf[0] === 0x89 && buf[1] === 0x50 && buf[2] === 0x4e && buf[3] === 0x47;
  const webp =
    buf.slice(0, 4).toString('ascii') === 'RIFF' && buf.slice(8, 12).toString('ascii') === 'WEBP';
  return jpg || png || webp;
}

function verifyImage(req, res, next) {
  if (!req.file) return next();
  try {
    const fd = fs.openSync(req.file.path, 'r');
    const buf = Buffer.alloc(12);
    fs.readSync(fd, buf, 0, 12, 0);
    fs.closeSync(fd);
    if (!looksLikeImage(buf)) {
      fs.unlinkSync(req.file.path);
      return next(new HttpError(400, 'The uploaded file is not a valid image'));
    }
    next();
  } catch (err) {
    next(err);
  }
}

module.exports = { upload, verifyImage, UPLOAD_DIR };
